+  { TK_INT16, "TK_INT16" },
+  { TK_INT32, "TK_INT32" },
+  { TK_INT64, "TK_INT64" },
+  { TK_UINT16, "TK_UINT16" },
+  { TK_UINT32, "TK_UINT32" },
+  { TK_UINT64, "TK_UINT64" },
+  { TK_FLOAT32, "TK_FLOAT32" },
