+  /* Extra TypeIdentifiers */
+  { TI_STRING8_SMALL, "TI_STRING8_SMALL" },
+  { TI_STRING8_LARGE, "TI_STRING8_LARGE" },
+  { TI_STRING16_SMALL, "TI_STRING16_SMALL" },
