+    case RTI_CDR_TYPE_OBJECT_TYPE_KIND_ALIAS_TYPE: /* ALIAS */
+      rtps_util_add_type_element_alias(element_tree, tvb, offset, encoding, info);
+      break;
+    case RTI_CDR_TYPE_OBJECT_TYPE_KIND_ARRAY_TYPE: /* ARRAY */
