+      ENC_LITTLE_ENDIAN);
+    offset += 1;
+    break;
+
+  /* String types with large bounds */
+  case TI_STRING8_LARGE:
+  case TI_STRING16_LARGE:
+    /* StringLTypeDefn: LBound (4 bytes) */
